using Studio.Core;
using Studio.Raple;

var adapter=new RapleAdapter(Path.GetFullPath(args.FirstOrDefault()??"../raple-realms-7-server"));var checks=0;
void Check(bool value,string label){if(!value)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
void Reject(Action action,string label){try{action();}catch(Exception error)when(error is ArgumentException or InvalidOperationException){Check(true,label);return;}throw new Exception("Expected rejection: "+label);}
const string entity="Cave Pirate Brawler";var file=adapter.Catalog().Single(e=>e.Id==entity).SourceFile;var supplied=File.ReadAllText(file);
const string source="""
using TKR.WorldServer.logic.behaviors;
namespace TKR.WorldServer.logic { public partial class BehaviorDb {
    static State StudioConstantBuild() {
        const int shots=3;
        const double radius=20;
        return new State("origin",new Shoot(radius,count:shots,coolDown:100));
    }
    private _ StudioConstantFragment=()=>Behav().Init("Cave Pirate Brawler",StudioConstantBuild());
} }
""";
const string target="namespace TKR.WorldServer.logic{public partial class BehaviorDb{private _ StudioConstantDestination=()=>Behav().Init(\"Cave Pirate Brawler\",new State(\"destination\"));}}";
BehaviorDocument Document(string text)=>new(text,adapter,sourceFile:file);
StudioProject Project(BehaviorDocument document)=>new(){SourceFile=file,Source=document.Source,EntityId=entity,Identities=document.Identities,Player=new(Invulnerable:true),Seed=7};
BehaviorFragment Capture(BehaviorDocument doc,BehaviorNode node,IEnumerable<FragmentBinding>? bindings=null)=>FragmentDependencies.Capture(adapter,Project(doc),doc,[node.Id],doc.CaptureFragment([node.Id],"Lexical constants",bindings:bindings));
var origin=Document(source);var node=origin.AllNodes.Single(n=>n.Kind=="Shoot");var ids=origin.Identities;var fragment=Capture(origin,node,[new(node.Id,"coolDown","cadence")]);
Check(fragment is{Version:2,Dependencies.Members.Count:0}&&fragment.Contents.Expressions.Single().Contains("const int @shots = 3")&&fragment.Contents.Expressions.Single().Contains("const double @radius = 20"),"Portable native expression carries typed lexical constants without copying unrelated scope code");
Check(fragment.Parameters.Single().Value.DefaultExpression=="100"&&fragment.Parameters.Single().DisplayExpression=="100","Template value spans follow the original constructor inside the capture wrapper");
Check(origin.Source==source&&origin.Identities.SequenceEqual(ids),"Capture leaves original scope source and identities untouched");
var output=Path.GetFullPath(".artifacts/constant-fragments");Directory.CreateDirectory(output);var saved=Path.Combine(output,"constants.rbsfrag");fragment.Save(saved);fragment=BehaviorFragment.Load(saved);
Check(fragment.Contents.Expressions.Single().Contains("@shots")&&fragment.Parameters.Single().Name=="cadence","Existing versioned JSON retains complete capture declarations and exposed inputs");
var destination=Document(target);var root=destination.Entities.Single().Root;var inserted=FragmentDependencies.Import(adapter,Project(destination),destination,0,root.Id,0,fragment,new Dictionary<string,string>{{"cadence","200"}});
Check(destination.Revision==1&&inserted.Count==1&&destination.Source.Contains("@shots = 3")&&SourceVerification.Check(adapter.ServerRoot,file,destination.Source).Accepted,"Import into a scope without either local compiles as one accepted source revision");
var accepted=destination.Source;Check(destination.Undo()&&destination.Source==target&&destination.Redo()&&destination.Source==accepted,"One Undo/Redo restores the whole portable lexical expression");
destination.LockedNodes.Add(root.Id);Reject(()=>FragmentDependencies.Import(adapter,Project(destination),destination,destination.Revision,root.Id,0,fragment),"Destination locks protect captured constants and native insertion together");destination.LockedNodes.Clear();
Reject(()=>FragmentDependencies.Import(adapter,Project(destination),destination,destination.Revision-1,root.Id,0,fragment),"Stale lexical fragment insertion rejects atomically");
Reject(()=>FragmentDependencies.Import(adapter,Project(destination),destination,destination.Revision,root.Id,0,fragment,new Dictionary<string,string>{{"cadence","\"invalid\""}}),"Invalid typed template input rejects inside the actual wrapped constructor");
await using(var baseline=await CompiledRuntime.StartAsync(adapter.ServerRoot,Project(origin),artifactRoot:Path.Combine(output,"baseline")))
await using(var portable=await CompiledRuntime.StartAsync(adapter.ServerRoot,Project(destination),artifactRoot:Path.Combine(output,"portable")))
{await baseline.AdvanceAsync(new(),100);await portable.AdvanceAsync(new(),100);Check(baseline.Shots.SequenceEqual(portable.Shots),"Fresh imported lexical constants preserve complete native first-volley payloads");Check(portable.Callbacks.Any(c=>c.Behavior.EndsWith(".Shoot")&&c.Origin?.NodeId!=null),"Wrapped construction retains accepted native callback provenance");}
var variants=new[]{
    ("const int shots=1+2; const double radius=20;","new Shoot(radius,count:shots,coolDown:100)"),
    ("const string label=\"quoted \\\" value\\n\"; const char letter='Z';","new Taunt(1,0,label+letter)"),
    ("const TKR.Shared.resources.ConditionEffectIndex condition=TKR.Shared.resources.ConditionEffectIndex.Invulnerable;","new ConditionEffectBehavior(condition)"),
    ("const float size=1.25f;","new Wander(size)"),
    ("const string name=null;","new HealEntity(8,name:name)"),
    ("const double value=double.NaN;","new Shoot(20,predictive:value)"),
    ("const uint color=uint.MaxValue;","new Grenade(2,30,color:color)"),
    ("const decimal value=1.5m;","new Shoot(20,count:(int)value)"),
    ("const long value=long.MinValue;","new Shoot(20,count:(int)(value+9223372036854775807L)+4)"),
    ("const ulong value=ulong.MaxValue;","new Shoot(20,count:(int)(value-18446744073709551612UL))")};
foreach(var (locals,expression) in variants)
{var text="namespace TKR.WorldServer.logic{public partial class BehaviorDb{static State StudioVariants(){"+locals+"return new State(\"variant\","+expression+");}private _ StudioVariantRegistration=()=>Behav().Init(\"Cave Pirate Brawler\",StudioVariants());}}";text="using TKR.WorldServer.logic.behaviors;"+text;var doc=Document(text);var selected=doc.AllNodes.Single(n=>n.Kind is "Shoot" or "Taunt" or "ConditionEffectBehavior" or "Wander" or "HealEntity" or "Grenade");var captured=Capture(doc,selected);var imported=Document(target);FragmentDependencies.Import(adapter,Project(imported),imported,0,imported.Entities.Single().Root.Id,0,captured);Check(SourceVerification.Check(adapter.ServerRoot,file,imported.Source).Accepted,"Portable constant preserves its original native type and value: "+locals);}
foreach(var changed in new[]{source.Replace("const int shots=3;","int shots=3;"),source.Replace("static State StudioConstantBuild()","static State StudioConstantBuild(int shots=3)").Replace("const int shots=3;","")})
{var doc=Document(changed);Reject(()=>Capture(doc,doc.AllNodes.Single(n=>n.Kind=="Shoot")),"Mutable local/parameter captures retain an explicit ownership boundary");}
var nameSource=source.Replace("count:shots","count:nameof(shots)==\"shots\"?shots:9");var nameDoc=Document(nameSource);var nameFragment=Capture(nameDoc,nameDoc.AllNodes.Single(n=>n.Kind=="Shoot"));Check(nameFragment.Contents.Expressions.Single().Contains("nameof(shots)"),"Lexical constant names remain available to nameof without replacing source identifiers");
var nameTarget=Document(target);FragmentDependencies.Import(adapter,Project(nameTarget),nameTarget,0,nameTarget.Entities.Single().Root.Id,0,nameFragment);await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,Project(nameTarget),artifactRoot:Path.Combine(output,"nameof"))){await native.AdvanceAsync(new(),100);Check(native.Shots.Single().Count==3,"Native nameof-dependent construction keeps the original chosen volley");}
var callerSource=source.Replace("count:shots","count:StudioConstantText(shots+1)").Replace("static State StudioConstantBuild()", "static int StudioConstantText(int value,[System.Runtime.CompilerServices.CallerArgumentExpression(\"value\")]string text=null)=>text==\"shots+1\"?value:9; static State StudioConstantBuild()");
var callerDoc=Document(callerSource);var callerFragment=Capture(callerDoc,callerDoc.AllNodes.Single(n=>n.Kind=="Shoot"));Check(callerFragment.Contents.Expressions.Single().Contains("(shots+1)"),"Capture preserves original argument spelling for native CallerArgumentExpression consumers");
var callerTarget=Document(target);FragmentDependencies.Import(adapter,Project(callerTarget),callerTarget,0,callerTarget.Entities.Single().Root.Id,0,callerFragment);await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,Project(callerTarget),artifactRoot:Path.Combine(output,"caller-text"))){await native.AdvanceAsync(new(),100);Check(native.Shots.Single().Count==4,"Original caller-argument text still selects the same native branch after import");}
var inline=destination.Definitions.Single(d=>d.Definition!.Label=="Inline factory");var shifted=new BehaviorDocument("// unrelated source prefix\n"+destination.Source,adapter,destination.Identities,file);Check(shifted.Definitions.Single(d=>d.Definition!.Label=="Inline factory").Definition!.Key==inline.Definition!.Key&&shifted.Definitions.Single(d=>d.Definition!.Label=="Inline factory").Root.Id==inline.Root.Id,"Inline factory ownership and identities survive unrelated source-position changes");
var spreadSource=source.Replace("new Shoot(radius,count:shots,coolDown:100)","children:[..new Behavior[]{new Shoot(radius,count:shots,coolDown:100)}]");var spreadDoc=Document(spreadSource);var spreadNode=spreadDoc.AllNodes.Single(n=>n.Kind=="Spread");var spreadFragment=Capture(spreadDoc,spreadNode);var spreadTarget=Document(target.Replace("new State(\"destination\")","new State(\"destination\",children:[])"));FragmentDependencies.Import(adapter,Project(spreadTarget),spreadTarget,0,spreadTarget.Entities.Single().Root.Id,0,spreadFragment);Check(SourceVerification.Check(adapter.ServerRoot,file,spreadTarget.Source).Accepted&&spreadTarget.Source.Contains("const int @shots"),"Portable spread inputs retain the original array and their captured constant scope");
var enumSource=source.Replace("const int shots=3;","const StudioLocalCount shots=StudioLocalCount.Three;").Replace("count:shots","count:(int)shots").Replace("static State StudioConstantBuild()","enum StudioLocalCount:byte { Three=3 } static State StudioConstantBuild()");var enumDoc=Document(enumSource);var enumFragment=Capture(enumDoc,enumDoc.AllNodes.Single(n=>n.Kind=="Shoot"));var enumTarget=Document(target);FragmentDependencies.Import(adapter,Project(enumTarget),enumTarget,0,enumTarget.Entities.Single().Root.Id,0,enumFragment);Check(enumFragment.Dependencies!.Members.Any(m=>m.Name=="StudioLocalCount")&&SourceVerification.Check(adapter.ServerRoot,file,enumTarget.Source).Accepted,"A captured source-owned enum bundles and renames its actual declaring type");
foreach(var constantType in new[]{"StudioLocalCount[]","System.Collections.Generic.List<StudioLocalCount>"})
{var referenceSource=enumSource.Replace("const StudioLocalCount shots=StudioLocalCount.Three;","const "+constantType+" shots=null;").Replace("count:(int)shots","count:shots==null?3:9");var referenceDoc=Document(referenceSource);var referenceFragment=Capture(referenceDoc,referenceDoc.AllNodes.Single(n=>n.Kind=="Shoot"));var referenceTarget=Document(target);FragmentDependencies.Import(adapter,Project(referenceTarget),referenceTarget,0,referenceTarget.Entities.Single().Root.Id,0,referenceFragment);Check(referenceFragment.Dependencies!.Members.Any(m=>m.Name=="StudioLocalCount")&&SourceVerification.Check(adapter.ServerRoot,file,referenceTarget.Source).Accepted,"Null reference constants retain source-owned array/generic element types: "+constantType);}
var phaseSource=source.Replace("const int shots=3;","const int shots=3;const string phase=\"origin\";").Replace("return new State(\"origin\",new Shoot(radius,count:shots,coolDown:100));","return new State(\"outer\",new State(phase,new Shoot(radius,count:shots,coolDown:100)));");var phaseDoc=Document(phaseSource);var phaseNode=phaseDoc.AllNodes.Single(n=>n.Kind=="State"&&n.Parameters.Any(p=>p.Expression=="phase"));var phaseFragment=Capture(phaseDoc,phaseNode);Check(phaseFragment.References.All(r=>r.Kind!="unresolved-phase"),"Compiler-known captured phase names retain reconciled ownership metadata");
var otherTarget=Document(target.Replace(entity,"Pirate Lieutenant"));var otherProject=Project(otherTarget) with{EntityId="Pirate Lieutenant"};FragmentDependencies.Import(adapter,otherProject,otherTarget,0,otherTarget.Entities.Single().Root.Id,0,phaseFragment);Check(SourceVerification.Check(adapter.ServerRoot,file,otherTarget.Source).Accepted&&otherTarget.Source.Contains("origin-copy"),"A captured native phase imports across entity owners with its real destination name reconciled");
Check(File.ReadAllText(file)==supplied,"Portable lexical capture, compilation and native playback preserve supplied game source");Console.WriteLine($"{checks} constant fragment checks passed.");
